  for (let i = 0; i < n; i++) {
    // [当前点的横坐标,当前点纵坐标相较于上一个点纵坐标的偏移量]
    const [cur_x, offset_y] = (await readline()).split(" ").map(Number);

    // cur_x - last_x 结果是上一个点到当前点的横向距离, 这个距离过程中，高度保持为abs(last_y)
    ans += (cur_x - last_x) * Math.abs(last_y);

    // 更新last_x, last_y
    last_x = cur_x;
    last_y += offset_y;
  }

  // 注意结束位置的处理
  if (end_x > last_x) {
    ans += (end_x - last_x) * Math.abs(last_y);
  }

  console.log(ans);
})();

C:
#include <stdio.h>
#include <math.h>

int main() {
    int n, end_x;
    scanf("%d %d", &n, &end_x);

    long ans = 0;

    long last_x = 0;
    long last_y = 0;

    for(int i=0; i<n; i++) {
        int cur_x, offset_y;
        scanf("%d %d", &cur_x, &offset_y);

        ans += (cur_x - last_x) * abs(last_y);

        last_x = cur_x;
        last_y += offset_y;
    }

    if(end_x > last_x) {
        ans += (end_x - last_x) * abs(last_y);
    }

    printf("%ld\n", ans);

    return 0;
}
